-- ===================== 02_install_change_log.sql =====================
-- sc-10850 -- V1 -> V2 offer mirror: products_change_log + capture trigger on products.
--
-- Every relevant change to `products` is queued in products_change_log,
-- whichever writer made it (seller feeds, order path, admin routes, scripts).
-- The mirror poller (sc-10825) drains the log; rows are deleted once V2
-- accepted them, so the log is a queue, not a history table.
--
-- The log only says WHICH product changed. The poller reads the current
-- products row and sends it with v1_id_product = id_product; V2 finds the
-- offer to update through its offer_v1_mapping table, so a reprice or DOT
-- change updates the same offer in place.
--
-- Run ONCE on V1 Postgres (PostgreSQL 17), as the OWNER of `products` (postgres).
-- Tested locally on PostgreSQL 18; nothing used here is newer than PostgreSQL 11.
--
-- Safe for V1:
--   * The trigger does exactly one INSERT: no lookups, no HTTP, nothing
--     computed. All filtering and mapping live in the poller.
--   * SECURITY DEFINER: every V1 writer role can log rows without new grants.
--   * Any error inside the trigger is downgraded to a WARNING, so the V1 write
--     that fired it always commits (the backfill, sc-10826, repairs a gap).
--   * lock_timeout: CREATE TRIGGER briefly locks `products`; if it cannot get
--     the lock within 3s it gives up instead of queueing behind checkout.
--
-- Undo: 002_uninstall.sql

BEGIN;

SET LOCAL lock_timeout = '3s';

CREATE TABLE IF NOT EXISTS products_change_log (
    id          bigserial   PRIMARY KEY,               -- capture order
    id_product  integer     NOT NULL,
    operation   text        NOT NULL CHECK (operation IN ('INSERT', 'UPDATE', 'DELETE')),
    -- copied from the row (the deleted row for DELETE): lets the poller route a
    -- delete to the right venture credential and filter sellers without a join
    id_seller   integer,
    venture     text,
    changed_at  timestamptz NOT NULL DEFAULT now(),    -- lag monitoring only, never a read cursor
    -- set by the poller once the change was published; the row is kept as a record
    sent        boolean     NOT NULL DEFAULT false,
    sent_at     timestamptz
);

-- Upgrade an existing log (installed before the sent flag existed). No-op otherwise.
ALTER TABLE products_change_log ADD COLUMN IF NOT EXISTS sent boolean NOT NULL DEFAULT false;
ALTER TABLE products_change_log ADD COLUMN IF NOT EXISTS sent_at timestamptz;

-- The poller only ever looks at unsent rows, oldest first: keep that fast as sent rows pile up.
CREATE INDEX IF NOT EXISTS products_change_log_unsent_idx
    ON products_change_log (id)
    WHERE NOT sent;

-- Rows the poller isolated as undeliverable (poison-row guard, sc-10825).
CREATE TABLE IF NOT EXISTS products_change_dead_letter (
    id          bigserial   PRIMARY KEY,
    id_product  integer     NOT NULL,
    payload     jsonb,
    error       text,
    attempts    integer     NOT NULL DEFAULT 0,
    parked_at   timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE products_change_log IS
    'V1 -> V2 offer mirror queue (sc-10850): one row per relevant products change, written by the '
    'products_change_log_capture trigger; the mirror poller (sc-10825) sets sent = true once it was published.';
COMMENT ON COLUMN products_change_log.id IS 'Capture order.';
COMMENT ON COLUMN products_change_log.id_product IS 'The products row that changed.';
COMMENT ON COLUMN products_change_log.operation IS 'INSERT, UPDATE or DELETE on products.';
COMMENT ON COLUMN products_change_log.id_seller IS 'Seller of the row (of the deleted row for DELETE).';
COMMENT ON COLUMN products_change_log.venture IS 'Venture of the row (of the deleted row for DELETE); picks the V2 credential.';
COMMENT ON COLUMN products_change_log.changed_at IS 'When the change was captured; lag monitoring only, never a read cursor.';
COMMENT ON COLUMN products_change_log.sent IS 'false = waiting to be published; true = published (row kept as a record).';
COMMENT ON COLUMN products_change_log.sent_at IS 'When the poller published it.';

COMMENT ON TABLE products_change_dead_letter IS
    'Changes the mirror poller (sc-10825) could not deliver to V2 after repeated attempts; waits for a person.';
COMMENT ON COLUMN products_change_dead_letter.id_product IS 'The products row that could not be sent.';
COMMENT ON COLUMN products_change_dead_letter.payload IS 'The V2 offer the poller tried to send.';
COMMENT ON COLUMN products_change_dead_letter.error IS 'Error returned by V2 (or raised while sending).';
COMMENT ON COLUMN products_change_dead_letter.attempts IS 'How many times it was tried before being parked.';
COMMENT ON COLUMN products_change_dead_letter.parked_at IS 'When it was moved here.';

CREATE OR REPLACE FUNCTION products_change_log_capture() RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
-- pg_temp last: a temporary table must never shadow the queue (it is searched
-- FIRST when not listed); the INSERT below is schema-qualified as well.
SET search_path = public, pg_temp
AS $$
DECLARE
    rec  record;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        -- UPDATE OF <columns> also fires when a column is only in the SET list;
        -- skip writes that changed none of the mirrored fields.
        IF  NEW.stock                   IS NOT DISTINCT FROM OLD.stock
        AND NEW.price                   IS NOT DISTINCT FROM OLD.price
        AND NEW.discounted_price        IS NOT DISTINCT FROM OLD.discounted_price
        AND NEW.active                  IS NOT DISTINCT FROM OLD.active
        AND NEW.dot                     IS NOT DISTINCT FROM OLD.dot
        AND NEW.sku_seller              IS NOT DISTINCT FROM OLD.sku_seller
        AND NEW.sku_manufacturer        IS NOT DISTINCT FROM OLD.sku_manufacturer
        AND NEW.id_seller               IS NOT DISTINCT FROM OLD.id_seller
        AND NEW.country_of_origin_short IS NOT DISTINCT FROM OLD.country_of_origin_short
        AND NEW.sell_only_by_pack       IS NOT DISTINCT FROM OLD.sell_only_by_pack
        THEN
            RETURN NULL;
        END IF;
    END IF;

    BEGIN
        IF TG_OP = 'DELETE' THEN
            rec := OLD;
        ELSE
            rec := NEW;
        END IF;

        INSERT INTO public.products_change_log (id_product, operation, id_seller, venture)
        VALUES (rec.id_product, TG_OP, rec.id_seller, rec.venture);
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'products_change_log_capture: could not log id_product % (%): % [%]',
            rec.id_product, TG_OP, SQLERRM, SQLSTATE;
    END;

    RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS products_change_log_capture ON products;

CREATE TRIGGER products_change_log_capture
    AFTER INSERT OR DELETE OR UPDATE OF
        stock, price, discounted_price, active, dot, sku_seller, sku_manufacturer,
        id_seller, country_of_origin_short, sell_only_by_pack
    ON products
    FOR EACH ROW
    EXECUTE FUNCTION products_change_log_capture();

COMMIT;

-- ===================== 04_scenarios.sql =====================
-- pg-cdc-pubsub: test scenarios. Each one makes a change to `products` the
-- way a real V1 writer does (same SQL as its source, noted per scenario), then
-- checks what the trigger wrote to `products_change_log`.
--
-- Needs a FRESH 01_products_table.sql (ids 1-6) and 02_install_change_log.sql.
-- Run in DBeaver against `cdc_pubsub_test` (Alt+X); the last two result tabs
-- show every scenario with PASS / FAIL and the totals.

-- Safety guard. On any other database (e.g. V1 production) it first makes this
-- session READ-ONLY, then stops with an error -- so even if the error is ignored
-- ("Ignore All" in DBeaver), every following write fails. Reconnect to clear it.
DO $$
BEGIN
    IF current_database() <> 'cdc_pubsub_test' THEN
        PERFORM set_config('default_transaction_read_only', 'on', false);
    END IF;
END $$;
DO $$
BEGIN
    IF current_database() <> 'cdc_pubsub_test' THEN
        RAISE EXCEPTION 'Wrong database %: this script only runs on cdc_pubsub_test. The session is now read-only.',
            current_database();
    END IF;
END $$;

-- ---------------------------------------------------------------- helpers ---

DROP TABLE IF EXISTS public.test_results;
CREATE TABLE public.test_results (
    id        serial PRIMARY KEY,
    scenario  text,
    expected  text,
    actual    text,
    result    text
);

-- start a scenario with an empty log
CREATE OR REPLACE FUNCTION public.test_start() RETURNS void
LANGUAGE sql AS $$ DELETE FROM public.products_change_log $$;

-- record expected vs actual
CREATE OR REPLACE FUNCTION public.test_assert(p_scenario text, p_expected text, p_actual text) RETURNS void
LANGUAGE sql AS $$
    INSERT INTO public.test_results (scenario, expected, actual, result)
    VALUES (p_scenario, p_expected, p_actual, CASE WHEN p_actual = p_expected THEN 'PASS' ELSE 'FAIL' END)
$$;

-- what the trigger logged since test_start(), e.g. "UPDATE 1 seller 100 th"
CREATE OR REPLACE FUNCTION public.test_logged() RETURNS text
LANGUAGE sql AS $$
    SELECT coalesce(string_agg(operation || ' ' || id_product || ' seller ' || coalesce(id_seller::text, '-')
                               || ' ' || coalesce(venture, '-'), ', ' ORDER BY id), '(nothing logged)')
    FROM public.products_change_log
$$;

-- --------------------------------------------- changes that must be logged ---

-- S01 sheet sync creates a product (seller-google-sheets _insert_tyre_to_mysql_db)
SELECT public.test_start();
INSERT INTO products (sku_manufacturer, sku, id_seller, price, dot, stock, active, venture, created_at, updated_at)
VALUES ('265/60r18', '100_265/60r18_0526', 100, 4280, '0526', 10, true, 'th', now(), now());
SELECT public.test_assert('S01 sheet sync: new product', 'INSERT 7 seller 100 th', public.test_logged());

-- S02 sheet sync updates stock (seller-google-sheets _update_dimensions)
SELECT public.test_start();
UPDATE products SET stock = 6, price_b_quik = 2900, active = true, updated_at = now() WHERE id_product = 1;
SELECT public.test_assert('S02 sheet sync: stock 8 -> 6', 'UPDATE 1 seller 100 th', public.test_logged());

-- S03 sheet sync deactivates a removed row (seller-google-sheets _inactivate_deleted_dimensions)
SELECT public.test_start();
UPDATE products SET stock = 0, active = false, updated_at = now() WHERE id_product = 3;
SELECT public.test_assert('S03 sheet sync: deactivate', 'UPDATE 3 seller 100 th', public.test_logged());

-- S04 api-seller refresh (api-seller update_products, plain branch)
SELECT public.test_start();
update products set active = true, stock = 5, price = 2996, discounted_price = null, discount_level = null,
    updated_at = now() where id_product = 2;
SELECT public.test_assert('S04 api-seller refresh', 'UPDATE 2 seller 100 th', public.test_logged());

-- S05 api-seller /disable-all-products: one statement for a whole seller
SELECT public.test_start();
update products set stock = 0, active = false where id_seller = 2010;
SELECT public.test_assert('S05 api-seller disable-all (seller 2010)',
    'UPDATE 4 seller 2010 th, UPDATE 5 seller 2010 th', public.test_logged());

-- S06 create_order sells the last 6 units: decrement, then active = false (create_order.py)
SELECT public.test_start();
UPDATE products SET stock = GREATEST(stock - 6,0) WHERE id_product = 1 returning stock;
UPDATE products SET active = false WHERE id_product = 1;
SELECT public.test_assert('S06 create_order: sold out', 'UPDATE 1 seller 100 th, UPDATE 1 seller 100 th',
    public.test_logged());

-- S07 order cancelled: stock restored (update_status.py)
SELECT public.test_start();
UPDATE products SET stock = stock + 6, active = true WHERE id_product = 1 returning stock;
SELECT public.test_assert('S07 update_status: cancel restores stock', 'UPDATE 1 seller 100 th', public.test_logged());

-- S08 seller-center order switch_to (order_listing/routes.py)
SELECT public.test_start();
update products set stock = 4, active = true where id_product = 2;
SELECT public.test_assert('S08 seller-center switch_to', 'UPDATE 2 seller 100 th', public.test_logged());

-- S09 update-mapping withdraws a wrong mapping (product_listing/routes.py)
SELECT public.test_start();
update products set sku = '100_' || sku_manufacturer || sku_seller || '-wrong_mapping_' || dot,
    sku_seller = sku_seller || '-wrong_mapping' where lower(sku_seller) = lower('A-3') and id_seller = 100;
SELECT public.test_assert('S09 update-mapping: -wrong_mapping', 'UPDATE 3 seller 100 th', public.test_logged());

-- S10 same-DOT reprice
SELECT public.test_start();
UPDATE products SET price = 3424 WHERE id_product = 1;
SELECT public.test_assert('S10 reprice 3210 -> 3424', 'UPDATE 1 seller 100 th', public.test_logged());

-- S11 floor move: the oldest DOT week changes
SELECT public.test_start();
UPDATE products SET dot = '1225' WHERE id_product = 1;
SELECT public.test_assert('S11 floor move (dot 0824 -> 1225)', 'UPDATE 1 seller 100 th', public.test_logged());

-- S12 seller-center update-product sets sell_only_by_pack (product_listing/routes.py)
SELECT public.test_start();
update products set price_bucket = '[]', sell_only_by_pack = true where id_product = 2;
SELECT public.test_assert('S12 sell_only_by_pack on', 'UPDATE 2 seller 100 th', public.test_logged());

-- S13 a Korea product changes
SELECT public.test_start();
UPDATE products SET stock = 7 WHERE id_product = 6;
SELECT public.test_assert('S13 Korea product stock', 'UPDATE 6 seller 3010 kr', public.test_logged());

-- S14 hard delete (seller-center-backend admin_utils)
SELECT public.test_start();
delete from products where id_product = 5;
SELECT public.test_assert('S14 hard delete keeps seller + venture', 'DELETE 5 seller 2010 th', public.test_logged());

-- --------------------------------------------- changes that must be ignored ---

-- S15 only updated_at changes
SELECT public.test_start();
UPDATE products SET updated_at = now() WHERE id_product = 1;
SELECT public.test_assert('S15 updated_at only', '(nothing logged)', public.test_logged());

-- S16 fields that are not mirrored
SELECT public.test_start();
UPDATE products SET discount_level = 3, price_bucket = 'x', price_b_quik = 1, country_of_origin_long = 'japan',
    sku = '100_245/45r18_renamed' WHERE id_product = 1;
SELECT public.test_assert('S16 unmirrored fields', '(nothing logged)', public.test_logged());

-- S17 values written but unchanged
SELECT public.test_start();
UPDATE products SET stock = stock, price = price, active = active WHERE id_product = 1;
SELECT public.test_assert('S17 no-op update', '(nothing logged)', public.test_logged());

-- S18 venture alone is not watched
SELECT public.test_start();
UPDATE products SET venture = 'th' WHERE id_product = 6;
UPDATE products SET venture = 'kr' WHERE id_product = 6;
SELECT public.test_assert('S18 venture only', '(nothing logged)', public.test_logged());

-- S19 a write that is rolled back
SELECT public.test_start();
BEGIN;
UPDATE products SET stock = 99 WHERE id_product = 1;
ROLLBACK;
SELECT public.test_assert('S19 rolled-back write', '(nothing logged)', public.test_logged());

-- ------------------------------------------------- V1 must never be blocked ---

-- S20 the log table is broken: the V1 write still commits (a WARNING is shown instead)
SELECT public.test_start();
ALTER TABLE public.products_change_log RENAME TO products_change_log_broken;
UPDATE products SET stock = 7 WHERE id_product = 1;
ALTER TABLE public.products_change_log_broken RENAME TO products_change_log;
SELECT public.test_assert('S20 broken log: V1 write still saved', '7',
    (SELECT stock::text FROM products WHERE id_product = 1));
SELECT public.test_assert('S20 broken log: nothing logged', '(nothing logged)', public.test_logged());

-- S21 a temporary table with the same name cannot steal the row
SELECT public.test_start();
CREATE TEMP TABLE products_change_log (id_product integer, operation text, id_seller integer, venture text);
UPDATE products SET stock = 8 WHERE id_product = 1;
SELECT public.test_assert('S21 temp table stays empty', '0', (SELECT count(*)::text FROM pg_temp.products_change_log));
DROP TABLE pg_temp.products_change_log;
SELECT public.test_assert('S21 real log got the row', 'UPDATE 1 seller 100 th', public.test_logged());

-- ------------------------------------------------------------------ result ---

SELECT id, scenario, expected, actual, result FROM public.test_results ORDER BY id;

SELECT result, count(*) AS scenarios FROM public.test_results GROUP BY result ORDER BY result DESC;
